import{z as n,x as A,o,c as p,q as r,j as t,D as e,d as B,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"抵押约束与房价","description":"","frontmatter":{"title":"抵押约束与房价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/collateral-house-prices.md","filePath":"econ/collateral-house-prices.md","lastUpdated":1791063341000}'),d={name:"econ/collateral-house-prices.md"};function c(m,a,C,u,T,h){const l=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="抵押约束与房价" tabindex="-1">抵押约束与房价 <a class="header-anchor" href="#抵押约束与房价" aria-label="Permalink to &quot;抵押约束与房价&quot;">​</a></h1><div class="epigraph"><p>住房既是消费又是抵押；房价进入借贷上限时，利率与信贷供给的脉冲被按揭渠道放大成消费与新建。</p><footer>—— Iacoviello, House Prices, Borrowing Constraints, and Monetary Policy in the Business Cycle, AER 2005；Kiyotaki–Moore 的住房版本</footer></div><p><a href="/econ/gertler-kiyotaki">上一课</a>把银行净值接到信贷。家庭侧最重要的抵押是房。本课缺口是 <strong>房价–LTV 循环</strong>，接到已有的家庭债务事实。不重写银行激励约束代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Iacoviello：耐心储蓄人与不耐心借款人，住房服务进效用，借款受房价×LTV 约束。货币紧缩降房价，收紧约束，借款人消费大降——比代表性欧拉大。与 Mian–Sufi 的截面一致。缺口是给家庭债务课一条 NK/DSGE 装置，而不是再列邮编回归。</p><p><span class="marginnote">术语翻译：LTV（loan-to-value，贷款价值比）就是银行「最多借你房价几成」的规矩：LTV 70% 时，100 万的房子最多贷 70 万，剩下 30 万是首付。关键在于这个上限是拿<strong>当期房价</strong>乘出来的——房价一动，全家能借的钱立刻跟着动。</span></p><p><span class="marginnote">Iacoviello, <em>AER</em> 95(3), 2005, 739–764。Kiyotaki, Michaelides and Nikolov；Guerrieri and Iacoviello 的偶尔绑定。住房供给弹性（Glaeser、Saiz）改 \\(q\\) 的响应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两类家庭，住房存量缓慢调整或土地固定。货币政策进名义利率，经贴现与还款进 \\(q\\)。银行可有可无：先硬 LTV，再接 GK 的按揭供给。偶尔绑定：繁荣时约束松，IRF 像普通 NK；崩溃时绑定，非线性。宏观审慎 LTV 直接动约束参数。</p>',9)),(o(),t(i,null,{default:e(()=>[s(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E5%88%A9%E7%8E%87%20%2F%20%E4%BF%A1%E8%B4%B7%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20PH%5B%22%E6%88%BF%E4%BB%B7%22%5D%0A%20%20PH%20--%3E%20LTV%5B%22%E6%8A%B5%E6%8A%BC%E4%B8%8A%E9%99%90%22%5D%0A%20%20LTV%20--%3E%20C%5B%22%E5%80%9F%E6%AC%BE%E4%BA%BA%E6%B6%88%E8%B4%B9%22%5D%0A%20%20C%20--%3E%20Y%5B%22%E9%9C%80%E6%B1%82%E4%B8%8E%E5%B0%B1%E4%B8%9A%22%5D%0A%20%20Y%20--%3E%20PH%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 HANK 两资产：住房常是非流动性资产，贫流动性与高 LTV 是表亲。不要两套模型各说各话：校准应对同一套 MPC 与住房财富弹性。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制仍是价格进约束。住房特殊处：服务流使 \\(q\\) 有消费需求支撑，不只资产需求；供给慢使短期弹性更靠需求与信贷。名义刚性债：利率重置快慢决定现金流通道 vs 房价通道。浮动利率经济（部分欧洲）对政策利率更敏感。",-1)),(o(),t(i,null,{default:e(()=>[s(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E5%86%B2%E5%87%BB%EF%BC%9A%E6%88%BF%E4%BB%B7%E4%B8%8B%E8%B7%8C%22%5D%20--%3E%20CAP%5B%22%E5%8F%AF%E5%80%9F%E4%B8%8A%E9%99%90%20%3D%20LTV%20%C3%97%20%E6%88%BF%E4%BB%B7%EF%BC%8C%E5%90%8C%E6%AD%A5%E7%BC%A9%E6%B0%B4%22%5D%0A%20%20CAP%20--%3E%20CONS%5B%22%E5%80%9F%E6%AC%BE%E4%BA%BA%E8%A2%AB%E8%BF%AB%E7%A0%8D%E6%B6%88%E8%B4%B9%22%5D%0A%20%20CONS%20--%3E%20DEM%5B%22%E6%80%BB%E9%9C%80%E6%B1%82%E4%B8%8B%E9%99%8D%EF%BC%8C%E6%94%B6%E5%85%A5%E4%B8%8E%E5%B0%B1%E4%B8%9A%E6%89%BF%E5%8E%8B%22%5D%0A%20%20DEM%20--%3E%20PH%5B%22%E6%88%BF%E4%BB%B7%E8%BF%9B%E4%B8%80%E6%AD%A5%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20PH%20--%3E%20CAP%0A%20%20SHOCK%20--%3E%20DEBT%5B%22%E5%90%8D%E4%B9%89%E5%80%BA%E5%8A%A1%E4%B8%8D%E5%8F%98%EF%BC%9A%E5%AE%9E%E9%99%85%E8%B4%9F%E6%8B%85%E5%8A%A0%E9%87%8D%22%5D%0A%20%20DEBT%20--%3E%20CONS%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：房价 100 万、LTV 70%，可借上限 70 万；房价跌到 80 万，上限立刻变 56 万——借贷能力一夜少了 14 万，缩水幅度是房价跌幅的 1.4 倍。而欠的 70 万债一分没少。这个「房价跌一成、可花少一成多」的杠杆，就是消费对房价的响应比标准模型大得多的原因。</span></p><p>预期：新闻式的未来租金或诊断性房价外推，会先松后紧约束，制造内生繁荣崩溃。</p><p><span class="marginnote">本课不估计全国房价的因子模型，不把 REIT 微观结构当宏观。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定最优 LTV 数字（审慎课）。不写土地使用法。商业地产与家庭住房机制类似、主体不同。下一课把名义价格水平本身拉进债务负担——债务通缩。</p><p><span class="marginnote">常见误区：以为房价影响经济只走「财富效应」——涨了觉得自己富了就多花点。实际上在有抵押约束的家庭那里，起作用的是<strong>借债上限</strong>这个硬闸门：房价一跌，想借钱也借不到，消费被迫砍，与心情无关。这也是为什么高 LTV 时期房价波动对宏观的杀伤力远大于低负债时期。</span></p><p>后课默认：房价经 LTV 放大货币与信贷冲击；绑定是状态依存的。下一课：通缩如何加重名义债。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>住房抵押把房价焊进家庭借贷上限。</li><li>货币与信贷脉冲对借款人消费的效应大于代表性欧拉。</li><li>偶尔绑定产生非线性 IRF。</li><li>出处：Iacoviello, <em>AER</em> 2005。</li></ul>',9))])}const P=n(d,[["render",c]]);export{f as __pageData,P as default};
